                + " JOIN person p ON p.sheet = m.sheet AND p.id = m.person_id WHERE m.sheet = ? ORDER BY m.position",
                (rs) -> {
                    List<PoolMember> list = crews.get(rs.getString("crew"));
                    if (list != null) {
                        list.add(crewMember(rs, "person_id"));
