package net.officefloor.hq.app.period;

import java.util.Map;

public record Period(String name, String from, String to, boolean closed, String closedTotal,
        Map<Long, String> closedPeople, boolean soft, Integer cap, Map<Long, String> closedCarried,
        Map<Long, String> openings, boolean locked) {

    /** Whether its figures are fixed: closed or soft-closed. */
    public boolean fixed() {
        return closed || soft;
    }
}
    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> list(String sheet) {
        return jdbc.query(COLUMNS + " WHERE sheet = ? ORDER BY from_date", ROW, sheet).stream()
                .map((p) -> withOpenings(sheet, withPeople(sheet, p))).toList();
    }

    /** The period with its people's opening balances. */
    private Period withOpenings(String sheet, Period period) {
        Map<Long, String> openings = new LinkedHashMap<>();
        jdbc.query("SELECT person, amount FROM period_opening WHERE sheet = ? AND period = ? ORDER BY person",
                (rs) -> {
                    openings.put(rs.getLong("person"), rs.getBigDecimal("amount").toPlainString());
                }, sheet, period.name());
        return new Period(period.name(), period.from(), period.to(), period.closed(), period.closedTotal(),
                period.closedPeople(), period.soft(), period.cap(), period.closedCarried(), openings, period.locked());
    }

-- A pool membership, a person's or a pool's, may carry a from-date and a to-date (each optional, the to-date never
-- before the from-date). A member whose dates do not include the sheet's today is left out of its pool entirely.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
ALTER TABLE pool_sub ADD COLUMN from_date DATE;
ALTER TABLE pool_sub ADD COLUMN to_date DATE;
-- Pools that are members of another pool, with a share percent like a person's. A pool is a member of at most one
-- pool (the primary key on sheet and member), never contains itself through any chain, and a chain of pools is at
-- most three deep. Its position is drawn from the same order as pool_member, so a pool's members, people and pools,
-- list in the order added.
CREATE TABLE pool_sub (
    sheet    VARCHAR(200)  NOT NULL,
    pool     VARCHAR(200)  NOT NULL,
    member   VARCHAR(200)  NOT NULL,
    share    DECIMAL(5, 2) NOT NULL,
    position INT           NOT NULL,
    PRIMARY KEY (sheet, member)
);

